    "context.normalBehavior.2": "Mail acceptance, sender/size registration, delivery, and queue removal appear on separate lines.",
    "context.logSources.0.description": "HTTP proxy traffic records. Inspect source, destination, method, volume, and outcome.",
    "context.logSources.1.description": "Normalized DNS queries and answers. Inspect client, qname, record type, and answer.",
